for (const item of $input.all()) {
  const preview = item.json.body?.body_preview || '';
  const dateMatch = preview.match(/\d{1,2}\/\d{1,2}\s+([^\s]+)/);
  const callType = dateMatch ? dateMatch[1] : 'Dispatch';
  const incidentMatch = preview.match(/([^\s]+)\s+INCIDENT/i);
  const townCode = incidentMatch ? incidentMatch[1].toUpperCase() : '';
  const townMap = { 'UC': 'Union City', 'WNY': 'West New York', 'WEE': 'Weehawken', 'GUTT': 'Guttenberg', 'NB': 'North Bergen' };
  const townFull = townMap[townCode] || townCode;
  let address = '';
  if (callType && townCode) {
    const regexString = `${callType}\\s+(.+?)\\s+${townCode}\\s+INCIDENT`;
    const addressMatch = preview.match(new RegExp(regexString, 'i'));
    if (addressMatch) address = addressMatch[1].trim();
  }
  let gmapsUrl = '';
  if (address && townFull) {
    const searchString = `${address}, ${townFull}, NJ`;
    gmapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(searchString)}`;
  }
  item.json.ntfy_title = townCode ? `${callType} - ${townCode}` : callType;
  item.json.address = address;
  item.json.townFull = townFull;
  item.json.gmapsUrl = gmapsUrl;
}
return $input.all();

return $input.all().map((item) => {
  const j = item.json || {};
  const body = j.body || {};
  const preview = String(body.body_preview || '').trim();
  const callType = String(j.ntfy_title || 'Dispatch').split(' - ')[0].trim() || 'Dispatch';
  const municipality = String(j.townFull || '').trim().toUpperCase();
  const address = String(j.address || '').trim();
  const rawId = body.incident_id || body.incidentId || body.id || body.event_id || body.eventId || '';
  const fallback = preview.toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').substring(0, 180);
  const sourceEventId = String(rawId || fallback || Date.now());
  const priorityText = `${callType} ${preview}`.toUpperCase();
  let priority = 4;
  if (/WORKING FIRE|STRUCTURE FIRE|2ND ALARM|SECOND ALARM|3RD ALARM|THIRD ALARM|MAYDAY|ENTRAPMENT|HAZMAT|MCI/.test(priorityText)) priority = 5;
  else if (/ALARM|FIRE|SMOKE|RESCUE|EMS|MEDICAL|MVC|MVA|ACCIDENT/.test(priorityText)) priority = 4;
  else priority = 3;
  const now = new Date().toISOString();
  const alert = {
    schema_version: '1.0',
    alert_id: `NHRFR_DISP:${sourceEventId}`,
    source: 'NHRFR_DISP',
    source_event_id: sourceEventId,
    category: 'PUBLIC_SAFETY',
    subtype: callType.toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, '') || 'DISPATCH',
    status: 'ACTIVE', event_action: 'NEW',
    title: j.ntfy_title || `NHRFR Dispatch${municipality ? ' - ' + municipality : ''}`,
    message: preview || 'NHRFR dispatch received.',
    priority, county: 'HUDSON', municipality,
    location: { label: address || municipality, address, state: 'NJ', zip: '', latitude: null, longitude: null, block: '', lot: '', qualifier: '', parcel_id: '' },
    tags: ['nhrfr', 'dispatch', callType.toLowerCase().replace(/[^a-z0-9]+/g, '-')].filter(Boolean),
    click_url: j.gmapsUrl || '', source_url: '', observed_at: now, source_updated_at: null, received_at: now, expires_at: null,
    metadata: { town_code: String(j.ntfy_title || '').split(' - ')[1] || '', parsed_address: address, original_preview: preview }
  };
  alert.search_text = [alert.source, alert.category, alert.subtype, alert.status, alert.county, alert.municipality, alert.location.label, alert.location.address, alert.title, alert.message, ...alert.tags].filter(Boolean).join(' ');
  return { json: alert };
});
